-- SQL Server preparation schema, v1. Amounts are scaled BIGINT (1 TL = 1,000,000 units).
-- Run only against a new, empty database. No destructive DROP statements.
SET XACT_ABORT ON;
BEGIN TRANSACTION;
CREATE TABLE dbo.meta ([key] nvarchar(100) NOT NULL PRIMARY KEY,[value] nvarchar(200) NOT NULL);
CREATE TABLE dbo.users (id bigint IDENTITY PRIMARY KEY,username nvarchar(100) NOT NULL UNIQUE,role varchar(10) NOT NULL DEFAULT 'editor' CHECK(role IN ('admin','editor','viewer')),password_hash nvarchar(300) NOT NULL,created_at nvarchar(40) NOT NULL);
CREATE TABLE dbo.sessions (token_hash varchar(64) NOT NULL PRIMARY KEY,user_id bigint NOT NULL REFERENCES dbo.users(id),csrf varchar(64) NOT NULL,expires_at bigint NOT NULL);
CREATE TABLE dbo.budget_years ([year] int NOT NULL PRIMARY KEY CHECK([year] BETWEEN 2000 AND 2100),reference_units bigint NOT NULL CHECK(reference_units>=0),tax_basis varchar(20) NOT NULL DEFAULT 'excluded' CHECK(tax_basis='excluded'));
CREATE TABLE dbo.budget_versions (id bigint IDENTITY PRIMARY KEY,[year] int NOT NULL REFERENCES dbo.budget_years([year]),name nvarchar(80) NOT NULL CHECK(LEN(LTRIM(RTRIM(name)))>0),description nvarchar(200) NOT NULL DEFAULT '',active int NOT NULL DEFAULT 0 CHECK(active IN (0,1)),created_at nvarchar(40) NOT NULL,budget_changed int CHECK(budget_changed IN (0,1)),budget_units bigint CHECK(budget_units>=0),UNIQUE([year],name));
CREATE UNIQUE INDEX one_active_version ON dbo.budget_versions([year]) WHERE active=1;
CREATE TABLE dbo.budget_categories (id bigint IDENTITY PRIMARY KEY,name nvarchar(200) NOT NULL CHECK(LEN(LTRIM(RTRIM(name)))>0),name_key nvarchar(200) COLLATE Turkish_100_BIN2 NOT NULL UNIQUE,sort_order bigint NOT NULL);
CREATE TABLE dbo.training_topics (id bigint IDENTITY PRIMARY KEY,name nvarchar(200) NOT NULL,name_key nvarchar(200) COLLATE Turkish_100_BIN2 NOT NULL UNIQUE);
CREATE TABLE dbo.budget_lines (id bigint IDENTITY PRIMARY KEY,version_id bigint NOT NULL REFERENCES dbo.budget_versions(id),category_id bigint NOT NULL REFERENCES dbo.budget_categories(id),[month] int NOT NULL CHECK([month] BETWEEN 1 AND 12),amount_units bigint NOT NULL CHECK(amount_units>=0),UNIQUE(version_id,category_id,[month]));
CREATE TABLE dbo.savings_items (id bigint IDENTITY PRIMARY KEY,version_id bigint NOT NULL REFERENCES dbo.budget_versions(id),title nvarchar(200) NOT NULL CHECK(LEN(LTRIM(RTRIM(title)))>0),amount_units bigint NOT NULL CHECK(amount_units>=0));
CREATE TABLE dbo.invoices (id bigint IDENTITY PRIMARY KEY,number nvarchar(100) NOT NULL CHECK(LEN(LTRIM(RTRIM(number)))>0),[year] int NOT NULL REFERENCES dbo.budget_years([year]),[month] int NOT NULL CHECK([month] BETWEEN 1 AND 12),note nvarchar(2000) NOT NULL DEFAULT '',status varchar(20) NOT NULL DEFAULT 'active' CHECK(status IN ('active','cancelled')),created_at nvarchar(40) NOT NULL,updated_at nvarchar(40) NOT NULL);
CREATE TABLE dbo.invoice_lines (id bigint IDENTITY PRIMARY KEY,training_topic_id bigint REFERENCES dbo.training_topics(id),invoice_id bigint NOT NULL REFERENCES dbo.invoices(id),category_id bigint NOT NULL REFERENCES dbo.budget_categories(id),training_name nvarchar(200) NOT NULL CHECK(LEN(LTRIM(RTRIM(training_name)))>0),amount_units bigint NOT NULL CHECK(amount_units>=0),foreign_units bigint CHECK(foreign_units>=0),currency varchar(3) NOT NULL DEFAULT '',rate_units bigint CHECK(rate_units>0),participant_count int NOT NULL CHECK(participant_count>=0),rd_participant_count int NOT NULL CHECK(rd_participant_count>=0),other_participant_count int NOT NULL CHECK(other_participant_count>=0),description nvarchar(2000) NOT NULL DEFAULT '',CHECK(foreign_units IS NULL OR (currency IN ('USD','EUR','GBP','CHF') AND rate_units IS NOT NULL)));
CREATE TABLE dbo.planned_payments (id bigint IDENTITY PRIMARY KEY,category_id bigint NOT NULL REFERENCES dbo.budget_categories(id),[year] int NOT NULL REFERENCES dbo.budget_years([year]),[month] int NOT NULL CHECK([month] BETWEEN 1 AND 12),description nvarchar(200) NOT NULL CHECK(LEN(LTRIM(RTRIM(description)))>0),amount_units bigint NOT NULL CHECK(amount_units>0),saving_units bigint NOT NULL DEFAULT 0 CHECK(saving_units>=0 AND saving_units<=amount_units),saving_note nvarchar(2000) NOT NULL DEFAULT '',status varchar(20) NOT NULL DEFAULT 'active' CHECK(status IN ('active','cancelled')));
CREATE TABLE dbo.planned_payment_invoice_links (id bigint IDENTITY PRIMARY KEY,payment_id bigint NOT NULL REFERENCES dbo.planned_payments(id),line_id bigint NOT NULL REFERENCES dbo.invoice_lines(id),amount_units bigint NOT NULL CHECK(amount_units>0),UNIQUE(payment_id,line_id));
CREATE TABLE dbo.audit_logs (id bigint IDENTITY PRIMARY KEY,user_id bigint NOT NULL REFERENCES dbo.users(id),action nvarchar(100) NOT NULL,entity nvarchar(100) NOT NULL,entity_id bigint,before_json nvarchar(max),after_json nvarchar(max),created_at nvarchar(40) NOT NULL);
CREATE INDEX invoice_period ON dbo.invoices([year],[month],status);
CREATE INDEX line_category ON dbo.invoice_lines(category_id,invoice_id);
CREATE INDEX payment_period ON dbo.planned_payments([year],[month],status);
COMMIT;
